     */
    long insertInvoice(String noPrefix, String kind, String sellerId, String buyerId, boolean buyerBooked,
                       BigDecimal totalAmount, String status, String blueInvoiceNo) {
        String tempNo = "TMP-" + UUID.randomUUID();
        jdbc.update(
