                .isInstanceOf(ApiException.class)
                .extracting(e -> ((ApiException) e).getCode())
                .isEqualTo("INSUFFICIENT_CREDIT");
        assertThat(creditService.getCredit("S1").availableLimit()).isEqualByComparingTo("0.00");
