    }

    private ConfirmResponse confirmBoth(String requestNo) {
        redFlushService.confirm(requestNo, new ConfirmRequest("SELLER", "AGREE"));
        return redFlushService.confirm(requestNo, new ConfirmRequest("BUYER", "AGREE"));
    }
